// shared/chief-review.ts
var CHIEF_REVIEW_LABEL = "paseo-chief.review";
function isChiefReviewChat(chat) {
  return Object.prototype.hasOwnProperty.call(chat.labels, CHIEF_REVIEW_LABEL);
}

// server/activity.ts
var TURN_TAIL = 80;
async function turnStarted(host, journal, { agent }) {
  const chat = await host.chatOf(agent.id);
  if (chat && !isChiefReviewChat(chat)) await journal.begin(chat.botId);
}
async function turnEnded(host, journal, scheduler, { agent, outcome }) {
  const chat = await host.chatOf(agent.id);
  if (!chat || isChiefReviewChat(chat)) return;
  const { botId } = chat;
  const title = chat.title?.trim() || agent.title?.trim() || "Untitled chat";
  await journal.end(botId, { id: agent.id, title });
  const { reply: reply2, tools } = lastTurn(botId === CHIEF_BOT_ID && outcome.kind === "canceled" ? [] : await latestItems(host, agent.id, botId === CHIEF_BOT_ID));
  if (botId === CHIEF_BOT_ID && outcome.kind === "completed" && !reply2.trim() && tools.length === 0) throw new Error("Chief's completed turn has no observable reply or tools.");
  if (chat.routineId) await scheduler.finished(chat.routineId, agent.id, outcome, reply2);
  if (outcome.kind === "canceled") return;
  const line = logLine({ at: /* @__PURE__ */ new Date(), chat: title, reply: reply2, tools, failure: outcome.kind === "failed" ? outcome.error.message : null });
  if (line) await appendDailyLog(botId, line);
}
async function latestItems(host, agentId, strict) {
  const page = await host.paseo?.agents.ref(agentId).timeline.refetch({ direction: "tail", projection: "projected", limit: TURN_TAIL }).catch((error) => {
    if (strict) throw error;
    return null;
  });
  return (page?.entries ?? []).map((entry) => entry.item);
}

// server/commands.ts
import { randomUUID as randomUUID5 } from "node:crypto";
import { readFile as readFile3 } from "node:fs/promises";
import { z as z20 } from "zod";
import { isAbsolute as isAbsolute2, join as join11 } from "node:path";
var MAX_COMMAND_BYTES = 16384;
var MAX_RULES_PER_BOT = 200;
var StoredRules = z20.object({ rules: z20.array(z20.object({ id: z20.string(), botId: z20.string(), command: z20.string(), cwd: z20.string() })) });
function storePath2() {
  return join11(pluginDataPath(), "commands.json");
}
function validateRule(command, cwd) {
  if (!command.trim() || Buffer.byteLength(command, "utf8") > MAX_COMMAND_BYTES || /[\p{Cc}]/u.test(command.replace(/[\t\r\n]/g, ""))) {
    throw new Error("The command must be text of at most 16 KB.");
  }
  if (redactSecrets(command) !== command) throw new Error("Commands with credentials in them can't be saved. Use an environment variable instead.");
  if (!isAbsolute2(cwd) || cwd.split(/[\\/]/).includes("..")) throw new Error("The folder must be an absolute path.");
}
function canAutoAllowCommands(chat) {
  return chat.botId !== CHIEF_BOT_ID && !isChiefReviewChat(chat);
}
var CommandAllowlist = class {
  constructor() {
    this.queue = Promise.resolve();
  }
  async load() {
    try {
      return StoredRules.parse(JSON.parse(await readFile3(storePath2(), "utf8"))).rules;
    } catch (error) {
      if (missingFile(error)) return [];
      throw new Error("Couldn't read saved command rules. The existing file was kept intact.", { cause: error });
    }
  }
  change(edit) {
    const run = async () => {
      const { rules, result } = edit(await this.load());
      await atomicWrite(storePath2(), JSON.stringify({ version: 1, rules }, null, 2));
      return result;
    };
    const next = this.queue.then(run);
    this.queue = next.catch(() => {
    });
    return next;
  }
  async list(botId) {
    return (await this.load()).filter((rule) => rule.botId === botId).map(({ botId: _botId, ...rule }) => rule);
  }
  async add(botId, command, cwd) {
    validateRule(command, cwd);
    return this.change((rules) => {
      const mine = rules.filter((rule2) => rule2.botId === botId);
      const same = mine.find((rule2) => rule2.command === command && rule2.cwd === cwd);
      if (same) return { rules, result: { id: same.id, command, cwd } };
      if (mine.length >= MAX_RULES_PER_BOT) throw new Error(`A bot can have at most ${MAX_RULES_PER_BOT} allowed commands.`);
      const rule = { id: randomUUID5(), command, cwd };
      return { rules: [...rules, { ...rule, botId }], result: rule };
    });
  }
  remove(botId, id) {
    return this.change((rules) => {
      const next = rules.filter((rule) => rule.botId !== botId || rule.id !== id);
      return { rules: next, result: next.length !== rules.length };
    });
  }
  /** Exact command and folder only: a longer command or another folder still asks. */
  async matches(botId, command, cwd) {
    return (await this.load()).some((rule) => rule.botId === botId && rule.command === command && rule.cwd === cwd);
  }
};

